import { expect, it } from "@effect/vitest";

import type { BenchmarkDefinition } from "@litellm-bench/contracts/metadata";

import { buildCatalog } from "./model.js";

const definition = {
  id: "sample",
  label: "Sample",
  kind: "sdk",
  artifact: "sdk",
  output_metrics: [{ id: "latency", unit: "ms", better: "lower" }],
  protocol: { question: "How fast?", scenarios: [], measurements: [], analyses: [] },
  jobs: [{ id: "base", canonical: true, runner: "ubuntu-24.04", config: {} }],
} as const satisfies BenchmarkDefinition;

it("builds browser-safe lookup fields while retaining validated planning metadata", () => {
  const result = buildCatalog([{ directory: "sample", definition }]);
  expect(result._tag).toBe("Catalog");
  if (result._tag === "Catalog") {
    expect(result.value.sample?.metrics).toEqual({ latency: { unit: "ms", better: "lower" } });
    expect(result.value.sample?.canonicalJob).toBe("base");
    expect(result.value.sample?.definition.protocol.question).toBe("How fast?");
  }
});

it("rejects mismatched directories, duplicate ids, and ambiguous canonical jobs", () => {
  const result = buildCatalog([
    { directory: "wrong", definition },
    {
      directory: "sample",
      definition: {
        ...definition,
        jobs: [
          ...definition.jobs,
          { id: "alternate", canonical: true, runner: "ubuntu-24.04", config: {} },
        ],
      },
    },
  ]);
  expect(result._tag).toBe("InvalidCatalog");
  if (result._tag === "InvalidCatalog") {
    expect(result.issues.map((issue) => issue.message)).toEqual([
      "benchmark id \"sample\" must match directory name",
      "benchmark must declare exactly one canonical job",
      "duplicate benchmark id: sample",
    ]);
  }
});

import { expect, it } from "@effect/vitest";
import { type RunContext, RunnerExecutionError } from "@litellm-bench/harness";
import { type PreparedEnvironment, PythonEnvironment } from "@litellm-bench/python-environment";
import { Effect } from "effect";
import { decodeImportFootprintSpec } from "../src/config.js";
import { ImportFootprintProbe } from "../src/probe.js";
import { makeImportFootprintRunner } from "../src/runner.js";

const measurements = {
  warmups: 0,
  samples: 1,
  timing: false,
  diagnostics: true,
  importtime: false,
  network: false,
  timeout_seconds: 120,
} as const;
const config = {
  workload: { name: "root-import", statement: "import litellm" },
  measurements,
};
const context: RunContext = {
  runId: "footprint-test",
  createdAt: "2026-09-13T00:00:00Z",
  artifactsDirectory: "/artifacts",
  host: {
    platform: "linux",
    architecture: "x86_64",
    host: "existing",
    node_version: process.version,
    ci: false,
  },
  spec: {
    case_id: "a".repeat(64),
    comparison_id: "b".repeat(64),
    benchmark: {
      id: "sdk-import-footprint",
      label: "Fresh-process LiteLLM import footprint",
      kind: "sdk",
      output_metrics: [],
      protocol: { question: "footprint", scenarios: [], measurements: [], analyses: [] },
    },
    job: {
      id: "base",
      canonical: true,
      runner: "test",
      requirements: { platform: "linux", architecture: "x86_64", python: "3.12" },
      config,
    },
    version: { version: "1", artifacts: {} },
    artifact: { requirement: "litellm==1", distribution: "litellm" },
  },
};
const prepared: PreparedEnvironment = {
  workspace: "/workspace",
  python: "/python",
  site_packages: ["/site"],
  installed_files: [],
  downloads: "/downloads",
  pip_report: "/report",
  artifacts: [],
  package_version: "1",
  python_metadata: { version: "3.12.10", implementation: "CPython" },
  uv_version: "uv",
  pip_version: "pip",
};

it.effect("rejects unsupported instrumentation and unknown configuration", () =>
  Effect.gen(function*() {
    for (
      const changes of [{ typo: true }, { measurements: { ...measurements, diagnostics: false } }, {
        measurements: { ...measurements, network: true },
      }, { profile: "diagnostic" }]
    ) {
      const candidate = {
        ...context,
        spec: { ...context.spec, job: { ...context.spec.job, config: { ...config, ...changes } } },
      };
      expect(
        (yield* Effect.flip(
          decodeImportFootprintSpec(candidate),
        ))._tag,
      ).toBe("InvalidRunnerConfig");
    }
  }));

it.effect("keeps first import and diagnostics separate and releases resources", () =>
  Effect.gen(function*() {
    const events: string[] = [];
    let sizes = 0;
    let preparations = 0;
    const runner = yield* makeImportFootprintRunner.pipe(
      Effect.provideService(ImportFootprintProbe, {
        installedSize: () =>
          Effect.sync(() => {
            events.push("size");
            return { logical_bytes: sizes++ === 0 ? 100 : 1_048_676, allocated_bytes: null };
          }),
        runFirstImport: (environment) =>
          Effect.sync(() => {
            events.push(`first:${environment.workspace}`);
          }),
        collectDiagnostics: (environment) =>
          Effect.sync(() => {
            events.push(`diagnostic:${environment.workspace}`);
            return { import_only_seconds: 0.1, new_module_count: 12, peak_rss_bytes: 2_097_152 };
          }),
        collectPeakRss: (environment) =>
          Effect.sync(() => {
            events.push(`rss:${environment.workspace}`);
            return 2_097_152;
          }),
      }),
      Effect.provideService(PythonEnvironment, {
        prepare: () =>
          Effect.acquireRelease(
            Effect.sync(() => {
              preparations += 1;
              events.push(`prepare:${preparations}`);
              return { ...prepared, workspace: `/workspace-${preparations}` };
            }),
            () =>
              Effect.sync(() => {
                events.push("release");
              }),
          ),
      }),
    );
    const result = yield* runner.run(context);
    expect(events).toEqual([
      "prepare:1",
      "prepare:2",
      "size",
      "first:/workspace-1",
      "size",
      "rss:/workspace-2",
      "diagnostic:/workspace-2",
      "release",
      "release",
    ]);
    expect(result.metrics.map(({ value }) => value)).toEqual([2, 12, 1]);
  }));

it.effect("releases the environment after probe failure", () =>
  Effect.gen(function*() {
    const events: string[] = [];
    const runner = yield* makeImportFootprintRunner.pipe(
      Effect.provideService(ImportFootprintProbe, {
        installedSize: () => Effect.succeed({ logical_bytes: 0, allocated_bytes: null }),
        runFirstImport: () => Effect.fail(new RunnerExecutionError({ message: "failed" })),
        collectDiagnostics: () => Effect.die("unreachable"),
        collectPeakRss: () => Effect.die("unreachable"),
      }),
      Effect.provideService(PythonEnvironment, {
        prepare: () =>
          Effect.acquireRelease(Effect.succeed(prepared), () =>
            Effect.sync(() => {
              events.push("release");
            })),
      }),
    );
    expect((yield* Effect.flip(runner.run(context)))._tag).toBe("RunnerExecutionError");
    expect(events).toEqual(["release", "release"]);
  }));

import { NodeServices } from "@effect/platform-node";
import { expect, it } from "@effect/vitest";
import { ProcessExecutor, ProcessExecutorLive } from "@litellm-bench/harness";
import { Effect, FileSystem, Path } from "effect";
import { currentHost } from "../src/config.js";
import { measureImportTime } from "../src/measurement.js";
import { ImportTimeProbe, ImportTimeProbeLive } from "../src/probe.js";
import { prepared, spec } from "./fixtures.js";

const withPython = <A, E, R>(
  effect: Effect.Effect<
    A,
    E,
    R | ImportTimeProbe | ProcessExecutor | FileSystem.FileSystem | Path.Path
  >,
) =>
  effect.pipe(
    Effect.provide(ImportTimeProbeLive),
    Effect.provide(ProcessExecutorLive),
    Effect.provide(NodeServices.layer),
  );

const environment = Effect.gen(function*() {
  const fs = yield* FileSystem.FileSystem;
  const path = yield* Path.Path;
  const executor = yield* ProcessExecutor;
  const workspace = yield* fs.makeTempDirectoryScoped({ prefix: "import-time-test-" });
  const { stdout } = yield* executor.execute({
    executable: "python3",
    args: ["-I", "-c", "import sys; print(sys.executable)"],
    cwd: workspace,
    timeoutMs: 5000,
  });
  const sitePackages = path.join(workspace, "site-packages");
  yield* fs.makeDirectory(sitePackages);
  return { ...prepared, python: stdout.trim(), workspace, site_packages: [sitePackages] };
});

it.live(
  "measures distinct isolated Python processes and collects importtime only afterward",
  () =>
    withPython(Effect.gen(function*() {
      const fs = yield* FileSystem.FileSystem;
      const path = yield* Path.Path;
      const target = yield* environment;
      const marker = path.join(target.site_packages[0]!, "processes");
      const statement = `import os, sys; assert sys.flags.isolated == 1; open(${
        JSON.stringify(marker)
      }, 'a').write(str(os.getpid()) + '\\n')`;
      const raw = yield* measureImportTime(
        target,
        {
          ...spec,
          workload: { ...spec.workload, statement },
          measurements: { ...spec.measurements, importtime: true },
        },
        target.workspace,
        currentHost,
      );
      const pids = (yield* fs.readFileString(marker)).trim().split("\n");
      expect(new Set(pids).size).toBe(7);
      expect(raw.timing.warmup_samples_seconds).toHaveLength(2);
      expect(raw.timing.fresh_process.samples_seconds).toHaveLength(3);
      expect(raw.timing.fresh_process.samples_seconds.every((value) => value > 0)).toBe(true);
      expect(raw.size.installed_before_first_run.logical_bytes).toBe(0);
      expect(raw.size.first_run_logical_delta_bytes).toBe(pids[0]!.length + 1);
      const log = yield* fs.readFileString(path.join(target.workspace, "importtime.log"));
      expect(log).toContain("import time:");
      expect(raw.diagnostics.importtime).toEqual({
        path: "importtime.log",
        bytes: Buffer.byteLength(log),
      });
    })),
  10000,
);

it.live(
  "preserves real Python exceptions and subprocess timeout messages",
  () =>
    withPython(Effect.gen(function*() {
      const target = yield* environment;
      const probe = yield* ImportTimeProbe;
      for (
        const [statement, expected] of [
          ["raise RuntimeError('probe exploded')", "probe exploded"],
          ["import time; time.sleep(5)", "TimeoutExpired"],
        ]
      ) {
        const error = yield* Effect.flip(
          probe.measureBatch(
            target,
            {
              ...spec,
              workload: { ...spec.workload, statement: statement! },
              measurements: { ...spec.measurements, timeout_seconds: 1 },
            },
            "first",
            1,
          ),
        );
        expect(error._tag).toBe("RunnerExecutionError");
        expect(error.message).toContain(expected);
      }
    })),
  10000,
);

import { expect, it } from "@effect/vitest";
import { Effect } from "effect";
import { decodeImportTimeSpec } from "../src/config.js";
import { context, spec } from "./fixtures.js";

const decode = (config: Record<string, unknown>) =>
  decodeImportTimeSpec({
    ...context,
    spec: {
      ...context.spec,
      job: { ...context.spec.job, config: config as typeof context.spec.job.config },
    },
  });

it.effect("decodes defaults without changing the submitted config", () =>
  Effect.gen(function*() {
    const decoded = yield* decodeImportTimeSpec(context);
    expect(decoded).toEqual(spec);
    expect(context.spec.job.config.profile).toBeUndefined();
  }));

for (
  const [name, changes] of [
    ["unknown config key", { typo: true }],
    ["unsupported profile", { profile: "diagnostic" }],
    ["null resolver", { resolver: null }],
    ["null environment", { environment: null }],
    ["zero samples", { measurements: { ...spec.measurements, samples: 0 } }],
    ["disabled timing", { measurements: { ...spec.measurements, timing: false } }],
    ["diagnostic instrumentation", { measurements: { ...spec.measurements, diagnostics: true } }],
    ["network instrumentation", { measurements: { ...spec.measurements, network: true } }],
    ["unknown nested key", { measurements: { ...spec.measurements, samplez: 5 } }],
  ] as const
) {
  it.effect(`rejects ${name}`, () =>
    Effect.gen(function*() {
      const error = yield* Effect.flip(decode({ ...context.spec.job.config, ...changes }));
      expect(error._tag).toBe("InvalidRunnerConfig");
    }));
}

it.effect("requires a declared Python runtime", () =>
  Effect.gen(function*() {
    const { requirements: _, ...job } = context.spec.job;
    const candidate = {
      ...context,
      spec: { ...context.spec, job },
    };
    const error = yield* Effect.flip(decodeImportTimeSpec(candidate));
    expect(error._tag).toBe("InvalidRunnerConfig");
  }));

